 //
 // Anything else: undefined.
 export function denyListed(argv: string[], cwd: string): Hit | undefined {
-  throw new Error('not implemented');
+  if (argv.length === 0) return undefined;
+  const cmd = argv[0].split('/').pop();
+  if (cmd === 'git') return gitHit(argv.slice(1));
+  if (cmd === 'rm') return rmHit(argv.slice(1), cwd);
+  if (cmd === 'find') return findHit(argv.slice(1), cwd);
+  return undefined;
+}
+
+const GIT_WITH_VALUE = new Set(['-C', '-c', '--git-dir', '--work-tree', '--namespace']);
+const PUSH_FORCE = new Set(['--force', '--force-with-lease', '--mirror', '--delete', '--prune']);
+
+// A path that cannot be resolved before the command runs: contains $, or is ~user.
+const unresolvable = (p: string) => p.includes('$') || /^~(?!\/|$)/.test(p);
+
+function gitHit(args: string[]): Hit | undefined {
+  let i = 0;
+  while (i < args.length && args[i].startsWith('-')) i += GIT_WITH_VALUE.has(args[i]) ? 2 : 1;
+  const sub = args[i];
+  const rest = args.slice(i + 1);
+  if (sub === 'push') {
+    const forced = rest.some(
+      (w) =>
+        PUSH_FORCE.has(w.split('=')[0]) ||
+        (/^-[a-zA-Z]+$/.test(w) && /[fd]/.test(w)) ||
+        (!w.startsWith('-') && /^[+:]/.test(w)),
+    );
+    if (forced) return { name: 'force-push', reason: 'git push would overwrite or delete remote refs' };
+  }
+  if (sub === 'reset' && rest.includes('--hard')) return { name: 'reset-hard', reason: 'git reset --hard discards uncommitted work' };
+  if (sub === 'clean' && !rest.some((w) => w === '-n' || w === '--dry-run')) {
+    const forced = rest.some((w) => w === '--force' || (/^-[a-zA-Z]+$/.test(w) && w.includes('f')));
+    if (forced) return { name: 'clean-force', reason: 'git clean -f deletes untracked files' };
+  }
+  return undefined;
+}
+
+function rmHit(args: string[], cwd: string): Hit | undefined {
+  const targets: string[] = [];
+  let recursive = false;
+  let endOfOpts = false;
+  for (const w of args) {
+    if (!endOfOpts && w === '--') endOfOpts = true;
+    else if (!endOfOpts && w.startsWith('--')) recursive ||= w === '--recursive';
+    else if (!endOfOpts && w.startsWith('-')) recursive ||= /[rR]/.test(w);
+    else targets.push(w);
+  }
+  if (!recursive) return undefined;
+  const outside = { name: 'rm-outside', reason: 'recursive rm outside the working directory' } as const;
+  if (targets.length === 0) return { ...outside, reason: 'recursive rm with no targets (they may come from xargs)' };
+  for (const t of targets) {
+    if (unresolvable(t) || !insideWorkspace(t, cwd) || sameDir(t, cwd)) return outside;
+  }
+  return undefined;
+}
+
+function findHit(args: string[], cwd: string): Hit | undefined {
+  if (!args.some((w) => w === '-delete' || w === '-exec' || w === '-execdir')) return undefined;
+  const firstFlag = args.findIndex((w) => w.startsWith('-'));
+  const starts = firstFlag === -1 ? args : args.slice(0, firstFlag);
+  for (const p of starts.length ? starts : ['.']) {
+    if (unresolvable(p) || !insideWorkspace(p, cwd)) {
+      return { name: 'rm-outside', reason: 'find deletes or runs commands outside the working directory' };
+    }
+  }
+  return undefined;
 }

