+
+  const lineOf = (idx: number) => content.slice(0, idx).split('\n').length;
+
+  // tier 1: exact
+  const hits: number[] = [];
+  for (let i = content.indexOf(old_text); i !== -1; i = content.indexOf(old_text, i + old_text.length)) hits.push(i);
+  if (hits.length > 0) {
+    const lines = hits.map(lineOf);
+    if (hits.length > 1 && !replace_all) {
+      return { error: `old_text matches ${hits.length} places (first at line ${lines[0]}, then ${lines.slice(1).join(', ')}); add context to make it unique or set replace_all` };
+    }
+    return {
+      content: content.split(old_text).join(new_text),
+      applied: { from: lines[0], to: lineOf(hits[hits.length - 1] + old_text.length - 1), tier: 'exact', count: hits.length },
+    };
+  }
+
+  // tiers 2 and 3: whole lines
+  const stripNl = (s: string) => s.replace(/\n$/, '');
+  const oldLines = stripNl(old_text).split('\n');
+  const newLines = stripNl(new_text) === '' ? [] : stripNl(new_text).split('\n');
+  const n = oldLines.length;
+  const lines = content.split('\n');
+  const leadingWs = (s: string) => s.match(/^\s*/)![0];
+  const firstNonBlank = (ls: string[]) => ls.find(l => l.trim() !== '') ?? '';
+
+  const tiers: [Tier, (s: string) => string][] = [
+    ['trailing-space', s => s.trimEnd()],
+    ['indentation', s => s.trim()],
+  ];
+  for (const [tier, norm] of tiers) {
+    const starts: number[] = [];
+    for (let i = 0; i + n <= lines.length; i++) {
+      if (oldLines.every((l, j) => norm(l) === norm(lines[i + j]))) starts.push(i);
+    }
+    if (starts.length === 0) continue;
+    if (starts.length > 1) {
+      return { error: `old_text matches ${starts.length} places (lines ${starts.map(i => i + 1).join(', ')}); add context to make it unique` };
+    }
+    const i = starts[0];
+    let repl = newLines;
+    if (tier === 'indentation') {
+      const oldInd = leadingWs(firstNonBlank(oldLines));
+      const winInd = leadingWs(firstNonBlank(lines.slice(i, i + n)));
+      repl = newLines.map(l => {
+        if (l.trim() === '') return '';
