--- a/edit.ts	2026-10-28 00:25:00
+++ b/edit.ts	2026-10-28 00:25:46
@@ -23,5 +23,81 @@
 // - nothing matched: message contains "not found", and when the first non-blank line of old_text (trimmed) occurs
 //   in some lines of content, "first line appears at line L1, L2" (at most 5 lines).
 export function applyEdit(content: string, edit: TextEdit): { content: string; applied: Applied } | { error: string } {
-  throw new Error('not implemented');
+  const { old_text: oldText, new_text: newText } = edit;
+  if (oldText === '') return { error: 'old_text is empty; use write to create or overwrite a file' };
+  if (oldText === newText) return { error: 'old_text and new_text are the same; nothing to change' };
+
+  const lineOf = (index: number) => content.slice(0, index).split('\n').length;
+  const span = stripNewline(oldText).split('\n').length;
+
+  // 1. exact
+  const starts: number[] = [];
+  for (let i = content.indexOf(oldText); i !== -1; i = content.indexOf(oldText, i + oldText.length)) starts.push(i);
+  if (starts.length > 1 && !edit.replace_all) {
+    return { error: `old_text matches ${starts.length} places (line ${starts.map(lineOf).join(', ')}); add context to make it unique or set replace_all` };
+  }
+  if (starts.length > 0) {
+    const from = lineOf(starts[0]);
+    const to = lineOf(starts[starts.length - 1]) + span - 1;
+    const next = edit.replace_all ? content.replaceAll(oldText, newText) : content.replace(oldText, newText);
+    return { content: next, applied: { from, to, tier: 'exact', count: starts.length } };
+  }
+
+  // 2 and 3: whole lines
+  const { lines, trailing } = splitLines(content);
+  const oldLines = stripNewline(oldText).split('\n');
+  const newLines = stripNewline(newText) === '' ? [] : stripNewline(newText).split('\n');
+  const m = oldLines.length;
+  const windows = (eq: (a: string, b: string) => boolean) => {
+    const hits: number[] = [];
+    for (let i = 0; i + m <= lines.length; i++) {
+      if (oldLines.every((l, j) => eq(lines[i + j], l))) hits.push(i);
+    }
+    return hits;
+  };
+  const oldIndent = indentOf(oldLines.find(l => l.trim() !== ''));
+  const tiers: [Tier, number[], (i: number) => string[]][] = [
+    ['trailing-space', windows((a, b) => a.trimEnd() === b.trimEnd()), () => newLines],
+    ['indentation', windows((a, b) => a.trim() === b.trim()), i => {
+      const windowIndent = indentOf(lines.slice(i, i + m).find(l => l.trim() !== ''));
+      return newLines.map(l => (l.trim() === '' || !l.startsWith(oldIndent) ? l : windowIndent + l.slice(oldIndent.length)));
+    }],
+  ];
+  for (const [tier, hits, replacement] of tiers) {
+    if (hits.length === 0) continue;
+    if (hits.length > 1) {
+      return { error: `old_text matches ${hits.length} places (line ${hits.map(i => i + 1).join(', ')}); add context to make it unique` };
+    }
+    const i = hits[0];
+    const out = [...lines.slice(0, i), ...replacement(i), ...lines.slice(i + m)];
+    return { content: joinLines(out, trailing), applied: { from: i + 1, to: i + m, tier, count: 1 } };
+  }
+
+  const probe = oldLines.find(l => l.trim() !== '')?.trim() ?? '';
+  const at = lines.flatMap((l, i) => (probe !== '' && l.includes(probe) ? [i + 1] : [])).slice(0, 5);
+  if (at.length > 0) {
+    return { error: `old_text not found; its first line appears at line ${at.join(', ')}` };
+  }
+  return { error: 'old_text not found' };
+}
+
+function stripNewline(s: string): string {
+  return s.endsWith('\n') ? s.slice(0, -1) : s;
+}
+
+function splitLines(content: string): { lines: string[]; trailing: boolean } {
+  const lines = content.split('\n');
+  if (lines.length > 1 && lines[lines.length - 1] === '') {
+    lines.pop();
+    return { lines, trailing: true };
+  }
+  return { lines, trailing: false };
+}
+
+function joinLines(lines: string[], trailing: boolean): string {
+  return lines.join('\n') + (trailing ? '\n' : '');
+}
+
+function indentOf(line: string | undefined): string {
+  return line?.match(/^\s*/)?.[0] ?? '';
 }

