+import { describe, expect, test } from 'bun:test';
+import { cart } from '../src/cart/cart.ts';
+import { totals } from '../src/order/total.ts';
+
+// Expected values worked by hand from the rules and region table in README.md.
+describe('pricing rules', () => {
+  test('bulk discount starts at exactly 10 units', () => {
+    // 10 pens = 1200; 5% off = 60; line 1140; shipping 800; tax 7% of 1940 = 135.8 -> 136
+    expect(totals(cart('US', [['PEN', 10]]))).toMatchObject({ subtotal: 1140, shipping: 800, tax: 136, total: 2076 });
+  });
+
+  test('bulk discount at exactly 50 units takes the 10% tier', () => {
+    // 50 pens = 6000; 10% off = 600; line 5400 >= 5000 ships free; tax 7% of 5400 = 378
+    expect(totals(cart('US', [['PEN', 50]]))).toMatchObject({ subtotal: 5400, shipping: 0, tax: 378, total: 5778 });
+  });
+
+  test('lines of the same sku are merged before bulk pricing', () => {
+    // 6 + 5 mugs = 11 units -> 5% off 4950 = 247.5 -> 248; line 4702 < 5000 pays shipping 800
+    // tax 7% of 5502 = 385.14 -> 385
+    expect(totals(cart('US', [['MUG', 6], ['MUG', 5]]))).toMatchObject({ subtotal: 4702, shipping: 800, tax: 385, total: 5887 });
+  });
+
+  test('free shipping is decided on the discounted subtotal, after the coupon', () => {
+    // 3 tees + 2 mugs = 5400; FLAT5 -> 4900 < 5000 so shipping 800; tax 7% of 5700 = 399
+    expect(totals(cart('US', [['TEE', 3], ['MUG', 2]], 'FLAT5'))).toMatchObject({ subtotal: 5400, coupon: 500, shipping: 800, tax: 399, total: 6099 });
+  });
+
+  test('UK free shipping threshold is 4000', () => {
+    // 2 bags = 4400 >= 4000 ships free; tax 20% of 4400 = 880
+    expect(totals(cart('UK', [['BAG', 2]]))).toMatchObject({ subtotal: 4400, shipping: 0, tax: 880, total: 5280 });
+  });
+});

